// Build a readable Slack alert from the Error Trigger payload
const d = $json || {};
const e = d.execution || {};
const w = d.workflow || {};
const err = e.error || {};

const text = [
  '\uD83D\uDD34 *n8n workflow FAILED*',
  `*Workflow:* ${w.name || 'unknown'}  (${w.id || '-'})`,
  `*Failed at node:* ${e.lastNodeExecuted || 'unknown'}`,
  `*Mode:* ${e.mode || '-'}`,
  `*Error:* ${err.message || 'no message'}`,
  e.url ? `*Open execution:* ${e.url}` : ''
].filter(Boolean).join('\n');

return [{ json: { text } }];
